// Read-only: do not open/save «הגדרות התאמה».
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_plus.json') });

const BADGE = 'מתאים לתחום שלכם';
const REASON_LABEL = 'למה זה מתאים לכם (AI):';
const SINGULAR = /(^|[\s,.])(לך|שלך)([\s,.]|$)/;

test.describe('Smart agent /recommendations — plural address (#1d74c2)', () => {
  test('Job recommendations — badge and AI reason use plural address @desktop @prod-safe #1d74c2', async ({ page }) => {
    // 1. Open /recommendations
    await page.goto('/recommendations');
    await expect(page.getByRole('heading', { level: 1, name: 'הסוכן החכם' })).toBeVisible();

    // 2. Tab «משרות (N)»
    const tab = page.getByRole('navigation', { name: 'הסוכן החכם' }).getByRole('link', { name: /^משרות \(\d+\)$/ });
    await tab.click();
    const n = Number((await tab.innerText()).match(/\d+/)![0]);
    expect(n).toBeGreaterThan(0);

    // Banner with «לכם»
    await expect(page.getByRole('heading', { level: 2, name: `מצאנו ${n} משרות שמתאימות לכם` })).toBeVisible();

    // 3. Every card: badge, AI reason, no «100% התאמה», no singular forms
    const cards = page.getByRole('main').getByRole('listitem').filter({ has: page.locator('a[href^="/collaborations/"]') });
    await expect(cards).toHaveCount(n);
    await expect(page.getByRole('main').getByText('100% התאמה')).toHaveCount(0);

    for (let i = 0; i < n; i++) {
      const card = cards.nth(i);
      await expect(card.getByText(BADGE, { exact: true })).toBeVisible();
      const label = card.getByText(REASON_LABEL, { exact: true });
      await expect(label).toHaveCount(1);
      const reason = ((await label.locator('..').innerText()).replace(REASON_LABEL, '')).trim();
      expect(reason.length, `card ${i + 1}: AI reason is empty`).toBeGreaterThan(0);
      expect(reason, `card ${i + 1}: singular address in AI reason`).not.toMatch(SINGULAR);
    }
  });
});
